  ]
}

{
  "proposals": [
    {
      "proposal": "Usunąć wymóg weryfikacji OTP dla Gości po 3 rezerwacjach (AC3) i zastąpić go cichym rate-limitingiem po stronie serwera z komunikatem o tymczasowej niedostępności, bez angażowania użytkownika w dodatkowy krok weryfikacji.",
      "rationale": "AC3 wprowadza nieoczekiwane tarcie w kluczowym przepływie konwersji (rezerwacja bez konta), który jest priorytetem UX o wadze 0.18 i 0.12. Weryfikacja OTP w połowie procesu rezerwacji jest najpoważniejszym ryzykiem porzucenia. Cichy rate-limiting po stronie serwera realizuje cel bezpieczeństwa bez widocznego tarcia dla użytkownika.",
      "affected_requirements": ["AC3", "FR2"]
    },
    {
      "proposal": "Zmodyfikować FR3 i NFR6 tak, aby MFA dla Specjalisty było wymagane wyłącznie przy pierwszej konfiguracji konta oraz przy logowaniu z nowego urządzenia lub po 30 dniach nieaktywności, z domyślnym zapamiętaniem urządzenia na 30 dni bez dodatkowego potwierdzenia ze strony użytkownika (automatyczne trusted device po pierwszym MFA).",
      "rationale": "Obecne brzmienie FR3 i NFR6 jest niejednoznaczne co do częstotliwości MFA, co stwarza ryzyko implementacji wymagającej MFA przy każdym logowaniu. Automatyczne trusted device po pierwszym MFA eliminuje codzienne tarcie dla Specjalistów, zachowując bezpieczeństwo i realizując cel onboardingu poniżej 5 minut (FR12, AC9).",
      "affected_requirements": ["FR3", "NFR6", "AC10", "FR12"]
    },
    {
      "proposal": "Dodać do FR5 i AC6 alternatywną ścieżkę anulowania po upływie 24h: zamiast wyłącznie 'kontaktu ze specjalistą', system powinien umożliwiać wysłanie prośby o anulowanie jednym przyciskiem, a specjalista zatwierdza lub odrzuca ją w ciągu 2h, z automatycznym anulowaniem jeśli brak odpowiedzi.",
      "rationale": "Obecna blokada anulowania po 24h z wymogiem samodzielnego kontaktu ze specjalistą jest sprzeczna z priorytetem UX 'minimalna liczba kroków' i 'elastyczność'. Przepływ z prośbą o anulowanie zachowuje kontrolę specjalisty (ważne dla Business i Security), ale eliminuje frustrację użytkownika wynikającą z konieczności szukania danych kontaktowych i samodzielnego kontaktu.",
      "affected_requirements": ["FR5", "AC6", "US4"]
    }
  ]
}

{
  "proposals": [
    {
      "proposal": "Zmiana NFR10 i FR15: pokrycie testami automatycznymi logiki biznesowej wynosi minimum 85% bez wyjątku dla MVP; cel 85% obowiązuje od pierwszego wydania produkcyjnego, nie po 3 miesiącach. Pokrycie integracji zewnętrznych (Stripe, Twilio, SendGrid) minimum 80% z formalnymi kryteriami akceptacji dla scenariuszy błędów (timeout płatności, webhook failure, odrzucenie transakcji).",
      "rationale": "Kompromis na 60% dla MVP jest najwyższym zidentyfikowanym ryzykiem - każdy release niesie wysokie ryzyko niewyktytych regresji w krytycznej logice rezerwacji i płatności. Podniesienie progu do 85% od pierwszego wydania eliminuje okno wysokiego ryzyka. Dodanie formalnych kryteriów dla scenariuszy błędów integracji Stripe eliminuje ryzyko niespójnych stanów rezerwacji.",
      "affected_requirements": ["FR15", "NFR10"]
    },
    {
      "proposal": "Zmiana NFR11: freeze kodu wynosi minimum 5 dni przed wydaniem produkcyjnym (nie 2 dni). Dodatkowo wprowadzenie wymogu izolowanego środowiska testowego funkcjonalnie identycznego z produkcją jako formalnego warunku koniecznego do release, z możliwością odtwarzania stanów systemu.",
      "rationale": "Freeze 2 dni jest niewystarczający dla pełnego cyklu testów regresji, szczególnie dla złożonych scenariuszy modyfikacji grafiku specjalisty i integracji płatności. 5 dni to minimum wymagane przez QA. Brak formalnego środowiska testowego uniemożliwia deterministyczne odtwarzanie błędów - bez tego wymagania kryteria akceptacji są niemożliwe do weryfikacji w kontrolowanych warunkach.",
      "affected_requirements": ["NFR11", "FR15"]
    },
    {
      "proposal": "Rozszerzenie AC8 o dodatkowe kryteria akceptacji dla scenariuszy brzegowych: AC8a - gdy pacjent nie odpowie na powiadomienie o zmianie terminu w ciągu 24h (nie 48h), system wysyła drugie przypomnienie; AC8b - gdy upłynie 48h bez odpowiedzi, system automatycznie anuluje rezerwację i rejestruje zdarzenie w logu audytowym z dokładnym znacznikiem czasu; AC8c - gdy płatność za rezerwację zostanie odrzucona lub przekroczy timeout, rezerwacja pozostaje w stanie 'oczekująca' przez maksymalnie 15 minut, po czym slot jest automatycznie zwalniany z powiadomieniem pacjenta.",
      "rationale": "Brak formalnych kryteriów akceptacji dla stanów pośrednich w scenariuszu 48h timeout i błędów płatności generuje średnie ryzyko niespójnych stanów danych. Precyzyjna specyfikacja tych scenariuszy jest niezbędna do napisania deterministycznych testów automatycznych i eliminuje subiektywną ocenę gotowości tych funkcjonalności.",
      "affected_requirements": ["AC8", "FR6", "FR8"]
    }
  ]
}

