User stories:
[{"id": "US1", "description": "Jako gość (niezalogowany użytkownik) chcę przeglądać dostępne terminy u specjalistów bez konieczności zakładania konta, aby ocenić ofertę przed podjęciem decyzji o rejestracji."}, {"id": "US2", "description": "Jako nowy użytkownik chcę zarejestrować się przez SSO (Google lub Apple) lub email z maksymalnie 4 polami formularza w czasie poniżej 60 sekund, aby szybko uzyskać dostęp do funkcji rezerwacji."}, {"id": "US3", "description": "Jako zalogowany użytkownik chcę zarezerwować wizytę u specjalisty w maksymalnie 3 krokach (wybór terminu, potwierdzenie danych, płatność) i otrzymać natychmiastowe potwierdzenie, aby sprawnie planować swoje wizyty."}, {"id": "US4", "description": "Jako zalogowany użytkownik chcę anulować zarezerwowaną wizytę jednym kliknięciem bez wypełniania formularza uzasadnienia, pod warunkiem że do wizyty pozostało minimum 24 godziny, aby elastycznie zarządzać swoim harmonogramem."}, {"id": "US5", "description": "Jako zalogowany użytkownik chcę przeglądać wyłącznie własne rezerwacje i dane profilu, aby mieć pewność że moje dane są chronione przed dostępem innych użytkowników."}, {"id": "US6", "description": "Jako zalogowany użytkownik chcę otrzymywać powiadomienia email lub SMS o potwierdzeniu rezerwacji, przypomnieniu przed wizytą oraz o modyfikacji lub anulowaniu wizyty przez specjalistę, aby być na bieżąco z moim harmonogramem."}, {"id": "US7", "description": "Jako specjalista chcę zalogować się do systemu z obowiązkowym uwierzytelnianiem dwuskładnikowym (MFA), aby zapewnić bezpieczeństwo mojego konta i danych moich pacjentów."}, {"id": "US8", "description": "Jako specjalista chcę dodawać, modyfikować i usuwać sloty czasowe w moim grafiku, aby zarządzać swoją dostępnością zgodnie z bieżącymi potrzebami."}, {"id": "US9", "description": "Jako specjalista chcę być informowany o próbie modyfikacji slotu z istniejącą rezerwacją i móc wybrać między powiadomieniem użytkownika z prośbą o akceptację a automatycznym anulowaniem z pełnym logowaniem zdarzenia, aby zachować kontrolę nad swoim grafikiem bez naruszania praw użytkowników."}, {"id": "US10", "description": "Jako specjalista chcę przeglądać wyłącznie własny grafik i przypisane do mnie rezerwacje, aby mieć pewność że dane innych specjalistów są dla mnie niedostępne."}, {"id": "US11", "description": "Jako specjalista chcę przejść onboarding z podstawową weryfikacją (potwierdzenie email i opcjonalne przesłanie dokumentu kwalifikacji) w jednej sesji, aby szybko rozpocząć przyjmowanie rezerwacji na platformie."}, {"id": "US12", "description": "Jako administrator chcę zarządzać wszystkimi użytkownikami, rolami i rezerwacjami w systemie, aby utrzymać porządek operacyjny i reagować na zgłoszenia wymagające interwencji."}, {"id": "US13", "description": "Jako administrator chcę przeglądać niemodyfikowalny dziennik audytowy wszystkich operacji w systemie (rezerwacje, anulowania, logowania, zmiany uprawnień), aby móc przeprowadzić pełny audyt w przypadku incydentu bezpieczeństwa lub sporu."}, {"id": "US14", "description": "Jako administrator chcę przeglądać raporty biznesowe (liczba rezerwacji, konwersja, przychody z prowizji i subskrypcji, retencja) z danymi zagregowanymi bez ujawniania danych osobowych, aby podejmować decyzje biznesowe oparte na danych."}, {"id": "US15", "description": "Jako administrator chcę otrzymywać automatyczne alerty o anomaliach behawioralnych (np. wielokrotne nieudane logowania, masowe anulowania, próby nieautoryzowanego dostępu), aby szybko reagować na potencjalne incydenty bezpieczeństwa."}, {"id": "US16", "description": "Jako użytkownik próbujący zarezerwować już zajęty termin chcę otrzymać natychmiastową informację o konflikcie i możliwość dołączenia do listy oczekujących (jeśli funkcja jest aktywna), aby nie tracić czasu na ponowne przeszukiwanie dostępnych terminów."}, {"id": "US17", "description": "Jako inżynier QA chcę mieć dostęp do dedykowanego środowiska testowego wiernie odwzorowującego produkcję, pełnej dokumentacji API oraz możliwości symulowania konfliktów rezerwacji i scenariuszy brzegowych, aby zapewnić wysoką jakość systemu przed każdym release."}]

