  "functional_requirements": [
    {
      "id": "FR1",
      "description": "System musi umozliwiac przegladanie listy specjalistow oraz ich dostepnych terminow w szybkim, responsywnym widoku dostepnym na urzadzeniach mobilnych i desktopowych."
    },
    {
      "id": "FR2",
      "description": "System musi umozliwiac uzytkownikowi utworzenie rezerwacji wizyty w krotkim flow z minimalnym zakresem wymaganych danych, przy czym potwierdzenie rezerwacji nastapi dopiero po atomowej walidacji dostepnosci slotu."
    },
    {
      "id": "FR3",
      "description": "System musi zapobiegac standardowym konfliktom rezerwacji poprzez blokade podwojnego zajecia tego samego terminu dla tego samego specjalisty oraz zapewniac bezpieczna obsluge wspolbieznosci podczas rezerwacji."
    },
    {
      "id": "FR4",
      "description": "System musi dopuszczac wyjatki od reguly konfliktu rezerwacji tylko dla roli Admin lub innej jawnie upowaznionej roli uprzywilejowanej, z obowiazkowym uzasadnieniem, dodatkowa autoryzacja i nieusuwalnym sladem audytowym."
    },
    {
      "id": "FR5",
      "description": "System musi umozliwiac uzytkownikowi anulowanie wlasnej rezerwacji zgodnie z konfigurowalna polityka czasowa, a interfejs ma pokazywac ograniczenia anulowania przed finalizacja akcji."
    },
    {
      "id": "FR6",
      "description": "Jesli anulowanie jest poza standardowym oknem czasowym, system moze dopuscic anulowanie wyjatkowe tylko po spelnieniu zdefiniowanych warunkow biznesowych oraz zapisaniu powodu i sladu audytowego; dla operacji wysokiego ryzyka wymagane jest dodatkowe potwierdzenie tozsamosci."
    },
    {
      "id": "FR7",
      "description": "System musi umozliwiac specjaliscie samodzielne zarzadzanie wlasnym grafikiem, w tym dodawanie, usuwanie i modyfikowanie slotow dostepnosci."
    },
    {
      "id": "FR8",
      "description": "System musi umozliwiac specjaliscie modyfikacje grafiku wplywajace na istniejace rezerwacje, ale kazda taka zmiana musi wymagac podania powodu, zostac zapisana w audycie oraz skutkowac automatycznym oznaczeniem dotknietych wizyt do powiadomienia lub dalszej obslugi."
    },
    {
      "id": "FR9",
      "description": "System musi obslugiwac co najmniej role Guest, User, Specialist i Admin z domyslnie ograniczonym dostepem do danych oraz podstawowym modelem uprawnien mozliwym do dalszego rozszerzenia bez wdrazania pelnego zlozonego RBAC w MVP."
    },
    {
      "id": "FR10",
      "description": "System musi wymagac MFA dla rol Specialist i Admin oraz dla uzytkownika przy operacjach wrazliwych, takich jak odzyskiwanie konta, zmiana danych kontaktowych i anulowanie wyjatkowe."
    },
    {
      "id": "FR11",
      "description": "System musi zapewniac szyfrowanie danych osobowych i danych o wizytach w tranzycie i w spoczynku oraz bezpieczne zarzadzanie sesja, w tym wygasanie i uniewaznianie sesji po zmianach krytycznych."
    },
    {
      "id": "FR12",
      "description": "System musi prowadzic niezmienialny audyt operacji dotyczacych logowania, rezerwacji, anulacji, zmian grafiku, wyjatkow od konfliktow i zmian uprawnien, zapisujac kto, co, kiedy, skad i z jakim skutkiem wykonal dana akcje."
    },
    {
      "id": "FR13",
      "description": "System musi udostepniac spojne, wersjonowane API oraz jednoznaczne stany rezerwacji i grafiku wraz z dozwolonymi przejsciami i przewidywalnymi kodami bledow mozliwymi do asercji w testach."
    },
    {
      "id": "FR14",
      "description": 'System musi wysylac czytelne powiadomienia o utworzeniu rezerwacji, anulowaniu oraz zmianie grafiku wplywajacej na istniejaca wizyte, z jasnym opisem skutku dla uzytkownika.'
    },
    {
      'id': 'FR15',
      'description': 'System musi udostepniac podstawowe raportowanie biznesowe obejmujace liczbe rezerwacji, anulacje, oblozenie specjalistow i przychod lub prowizje.'
    },
    {
      'id': 'FR16',
      'description': 'System powinien byc zaprojektowany jako skalowalny poziomo dla wzrostu liczby uzytkownikow, specjalistow i operacji kalendarzowych przy wykorzystaniu prostych komponentow i gotowych uslug tam, gdzie obniza to koszt MVP.'
    },
    {
      'id': 'FR17',
      'description': 'System musi zapewniac obserwowalnosc produkcyjna obejmujaca logi aplikacyjne, zdarzenia bezpieczenstwa, monitoring bledow oraz metryki kluczowych przeplywow rezerwacji i anulowania na potrzeby operacyjne, QA i analizy biznesowej.'
    }
  ]
}

