{
  "non_functional_requirements": [
    {
      "id": "NFR1",
      "description": "System musi zapewniać czas odpowiedzi dla kluczowych operacji przeglądania dostępnych terminów na poziomie p95 <= 2 s przy nominalnym obciążeniu MVP, aby wspierać wysoką konwersję i użyteczność mobilną."
    },
    {
      "id": "NFR2",
      "description": "System musi być skalowalny horyzontalnie dla odczytów dostępności i operacji rezerwacyjnych bez konieczności istotnej przebudowy architektury, z rozdzieleniem warstw aplikacyjnych i danych oraz możliwością dodawania instancji usług."
    },
    {
      "id": "NFR3",
      "description": "System musi zapewniać integralność danych rezerwacji poprzez atomowość operacji, kontrolę współbieżności i idempotencję dla tworzenia oraz anulowania rezerwacji, tak aby równoległe żądania nie powodowały niespójności."
    },
    {
      "id": "NFR4",
      "description": "System musi stosować szyfrowanie TLS dla transmisji oraz szyfrowanie danych wrażliwych w spoczynku i w kopiach zapasowych, zgodnie z wymaganiami ochrony danych i minimalizacji ryzyka wycieku."
    },
    {
      "id": "NFR5",
      "description": "System musi wymuszać MFA dla ról Specialist i Administrator w MVP oraz stosować bezpieczne zarządzanie sesją, w tym ograniczony czas życia sesji, rotację tokenów i unieważnianie sesji po zmianie hasła lub wzroście ryzyka."
    },
    {
      "id": "NFR6",
      "description": "System musi implementować RBAC zgodny z zasadą najmniejszych uprawnień oraz ograniczeniem dostępu do zasobów własnych, przy czym uprawnienia administracyjne muszą być odseparowane od zwykłych kont użytkowników."
    },
    {
      "id": "NFR7",
      "description": "System musi prowadzić niezmienialne logi audytowe dla logowań, rezerwacji, anulowań, zmian grafiku, wyjątków od konfliktów i zmian uprawnień wraz z identyfikatorami korelacyjnymi, tak aby umożliwić dochodzenie incydentów i testowalność operacji."
    },
    {
      "id": "NFR8",
      "description": "System musi udostępniać spójny, wersjonowany i deterministyczny model błędów oraz odpowiedzi API/UI dla scenariuszy sukcesu i błędu, aby wspierać automatyzację testów, diagnostykę i przewidywalność UX."
    },
    {
      "id": "NFR9",
      "description": "System musi zapewniać obserwowalność produkcyjną obejmującą logi techniczne, metryki, alerty bezpieczeństwa i śledzenie zdarzeń wysokiego ryzyka, w tym nietypowych anulacji, masowych zmian grafików i prób obejścia polityk czasowych."
    },
    {
      "id": "NFR10",
      "description": "System musi być projektowany mobile-first i spełniać podstawowe wymagania dostępności interfejsu dla kluczowych ścieżek przeglądania terminów, rezerwacji i anulowania bez zwiększania liczby kroków ponad minimum operacyjne."
    },
    {
      "id": "NFR11",
      "description": "System musi utrzymywać prostotę MVP poprzez ograniczenie liczby wariantów procesów wyjątkowych do zamkniętej, konfigurowalnej listy oraz zakaz nieudokumentowanych wyjątków obsługiwanych poza systemem."
    },
    {
      "id": "NFR12",
      "description": "System musi umożliwiać wdrażanie zmian funkcjonalnych i eksperymentów biznesowych przez konfigurację lub feature flagi tam, gdzie nie narusza to bezpieczeństwa, integralności danych ani kompatybilności kontraktów."
    },
    {
      "id": "NFR13",
      "description": "System musi posiadać mierzalne kryteria akceptacji dla funkcji wysokiego ryzyka oraz minimalny zestaw testów automatycznych obejmujących współbieżność rezerwacji, polityki anulowania, uprawnienia ról i zmiany grafiku wpływające na istniejące wizyty."
    },
    {
      "id": "NFR14",
      "description": "System musi zachowywać kompatybilność wsteczną wersjonowanych interfejsów API w obrębie wersji głównej lub dostarczać kontrolowany mechanizm migracji kontraktowej dla klientów i testów integracyjnych."
    },
    {
      "id": "NFR15",
      "description": "System musi zapewniać odzyskiwalność operacyjną przez regularne kopie zapasowe danych rezerwacji, grafików i audytu oraz procedurę odtworzeniową o udokumentowanym i przetestowanym przebiegu."
    },
    {
      "id": "NFR16",
      "description": "System musi minimalizować zakres przetwarzanych i prezentowanych danych osobowych zgodnie z potrzebą roli oraz maskować dane tam, gdzie pełny wgląd nie jest konieczny do wykonania zadania."
    }
  ],
  "user_stories": [
    {
      "id": "US1",
      "description": "Jako gość chcę przeglądać dostępne terminy i podstawowe profile specjalistów bez zakładania konta, aby szybko zdecydować czy chcę zarezerwować wizytę."
    },
    {
      "id": "US2",
      "description": "Jako użytkownik chcę zarezerwować wybrany termin w krótkim procesie z minimalną liczbą pól, aby szybko sfinalizować wizytę."
    },
    {
      "id": "US3",
      "description": "Jako użytkownik chcę zobaczyć jednoznaczny komunikat, gdy termin został właśnie zajęty przez inną osobę, aby od razu wybrać inny slot bez niepewności co się stało."
    },
    {
      "id": "US4",
      "description": "Jako użytkownik chcę widzieć swoje nadchodzące i anulowane rezerwacje wraz ze statusem oraz zasadami anulowania, aby rozumieć jakie działania są jeszcze dostępne."
    },
    {
      "id": "US5",
      "description": 'Jako użytkownik chcę anulować własną wizytę w samoobsłudze przed upływem limitu czasowego, aby nie musieć kontaktować się z obsługą.'
    },
    {
      'id': 'US6',
      'description': 'Jako użytkownik chcę otrzymać prosty komunikat, gdy anulowanie jest już niedozwolone lub wymaga trybu wyjątkowego, aby wiedzieć jaki jest następny krok.'
    },
    {
      'id': 'US7',
      'description': 'Jako specjalista chcę zarządzać własnym grafikiem przez dodawanie, edycję i usuwanie dostępności, aby kontrolować kiedy użytkownicy mogą się do mnie zapisywać.'
    },
    {
      'id': 'US8',
      'description': 'Jako specjalista chcę modyfikować grafik wpływający na istniejące rezerwacje dopiero po dodatkowym potwierdzeniu i podaniu powodu, aby ograniczyć przypadkowe lub nieautoryzowane zmiany.'
    },
    {
      'id': 'US9',
      'description': 'Jako specjalista chcę widzieć skutki planowanej zmiany grafiku dla istniejących wizyt przed jej zatwierdzeniem, aby świadomie podjąć decyzję.'
    },
    {
      'id': 'US10',
      'description': 'Jako administrator chcę konfigurować polityki anulowania oraz zamkniętą listę wyjątków od konfliktów rezerwacji, aby kontrolować równowagę między obłożeniem, przychodem a ryzykiem nadużyć.'
    },
    {
      'id': 'US11',
      'description': 'Jako administrator chcę autoryzować lub nadzorować wyjątki wysokiego ryzyka związane z konfliktami rezerwacji i zmianami grafiku, aby zachować audytowalność oraz integralność harmonogramów.'
    },
    {
      'id': 'US12',
      'description': 'Jako administrator chcę mieć dostęp do podstawowych raportów o liczbie rezerwacji, anulacjach, obłożeniu i przychodzie, aby oceniać skuteczność MVP i podejmować decyzje biznesowe.'
    },
    {
      'id': 'US13',
      'description': 'Jako specjalista chcę logować się z MFA do panelu zarządzania grafikiem i wizytami, aby chronić konto przed przejęciem.'
    },
    {
      'id': 'US14',
      'description': 'Jako administrator bezpieczeństwa chcę mieć pełny ślad audytowy logowań, zmian grafików, rezerwacji, anulowań i wyjątków od reguł, aby móc analizować incydenty oraz nadużycia.'
    },
    {
      'id': 'US15',
      'description': 'Jako tester QA chcę mieć deterministyczne reguły konfliktów rezerwacji, anulowania i uprawnień wraz ze spójnymi kodami błędów, aby przygotować automatyczne testy regresji.'
    },
    {
      'id': 'US16',
      'description': 'Jako właściciel produktu chcę móc uruchamiać podstawowe opcje monetyzacji i eksperymenty konfiguracyjne bez dużych zmian kodu, aby szybciej walidować model biznesowy.'
    }
  ]
}

