    },
    {
      "id": "AC7",
      "given": "specjalista jest poprawnie uwierzytelniony do panelu zarządzania z użyciem MFA",
      "when": "dodaje, edytuje lub usuwa własną dostępność w grafiku",
      "then": "system pozwala zarządzać wyłącznie jego grafikiem, waliduje uprawnienia i zapisuje każdą zmianę w śladzie audytowym"
    },
    {
      "id": "AC8",
      "given": "specjalista planuje zmianę grafiku, która wpływa na istniejące rezerwacje",
      "when": "próbuje zatwierdzić taką zmianę",
      "then": "system najpierw pokazuje listę skutków dla istniejących wizyt, wymaga dodatkowego potwierdzenia oraz podania powodu zmiany, a bez tych danych nie pozwala jej zapisać"
    },
    {
      "id": "AC9",
      "given": "zmiana grafiku lub konflikt rezerwacji należy do kategorii wysokiego ryzyka zgodnie z konfiguracją administratora",
      "when": "specjalista lub użytkownik inicjuje operację objętą wyjątkiem",
      "then": "system nie wykonuje jej automatycznie, oznacza sprawę jako wymagającą autoryzacji lub nadzoru administratora, zachowuje pełen kontekst decyzji i blokuje finalizację do czasu rozstrzygnięcia zgodnie z regułami"
    },
    {
      "id": "AC10",
      "given": "administrator ma odpowiednie uprawnienia konfiguracyjne",
      "when": "ustawia polityki anulowania, zamkniętą listę wyjątków od konfliktów rezerwacji oraz podstawowe przełączniki konfiguracyjne dla monetyzacji i eksperymentów MVP",
      "then": "system zapisuje konfigurację bez potrzeby zmian kodu, wersjonuje ją i stosuje nowe reguły do kolejnych operacji zgodnie z datą wejścia w życie"
    },
    {
