      'then': 'system nie dopuszcza do panelu, zwraca spójny kod błędu uwierzytelnienia i zapisuje próbę w audycie'
    },
    {
      'id': 'AC14',
      'given': 'tester QA lub klient API wykonuje operacje rezerwacji, anulowania, logowania albo modyfikacji grafiku',
      'when': 'wystąpi sukces lub błąd biznesowy związany z konfliktem, polityką anulowania albo uprawnieniami',
      'then': 'system zwraca deterministyczne reguły rozstrzygnięcia oraz spójne kody wyników możliwe do użycia w automatycznych testach regresji'
    }
  ]
