      "name": "Administrator",
      "permissions": [
        "zarządzanie kontami użytkowników i specjalistów",
        "przeglądanie logów audytowych",
        "konfiguracja reguł systemowych i feature flags",
        "dostęp do raportów KPI i monetyzacji",
        "zarządzanie modelami cenowymi i wariantami A/B"
      ]
    }
  ],
  "functional_requirements": [
    {
      "id": "FR1",
      "description": "Rejestracja w 2 krokach (imię, email, hasło min. 10 znaków dla Użytkownika, min. 12 dla Specjalisty/Admina) bez blokowania dostępu; weryfikacja email prezentowana jako nieinwazyjny baner przez 7 dni, nie blokuje rezerwacji."
    },
    {
      "id": "FR2",
      "description": "Uwierzytelnianie przez SSO (Google/Apple) lub email+hasło; MFA obowiązkowe dla Specjalisty i Administratora (push notification lub TOTP), opcjonalne dla Użytkownika; sesje 7 dni dla Użytkownika, 8h dla Specjalisty i Administratora."
    },
    {
      "id": "FR3",
      "description": "Widok kalendarza dostępnych terminów z filtrowaniem po specjalizacji i dacie; ładowanie poniżej 1s (p95), max 2s; użytkownik widzi wyłącznie wolne sloty bez danych innych użytkowników."
    },
    {
      "id": "FR4",
      "description": "Rezerwacja w 3 krokach (wybór terminu, potwierdzenie danych, płatność/finalizacja) z max 4 polami; natychmiastowe potwierdzenie z powiadomieniem email/SMS do Użytkownika i Specjalisty."
    },
    {
      "id": "FR5",
      "description": "System zapobiega konfliktom rezerwacji przez optimistic locking; wyjątek awaryjny dopuszczalny wyłącznie gdy slot ma status CANCELLED/EXPIRED, autoryzowany przez Specjalistę lub Administratora i logowany z uzasadnieniem min. 20 znaków."
    },
    {
      "id": "FR6",
      "description": "Anulowanie jednym przyciskiem z pojedynczym potwierdzeniem; bezpłatne ponad 24h przed wizytą; po granicy 24h wymaga wyboru powodu z listy i podlega polityce zwrotów; każde anulowanie logowane z timestampem UTC."
    },
    {
      "id": "FR7",
      "description": "Specjalista zarządza grafikiem (dodawanie, modyfikacja, usuwanie slotów); modyfikacja slotu z rezerwacją wymaga potwierdzenia, powiadomienia Użytkownika i propozycji alternatywy lub pełnego zwrotu; każda zmiana logowana."
    },
    {
      "id": "FR8",
      "description": "Integracja ze Stripe lub PayU obsługująca model prowizyjny i subskrypcyjny; brak własnego przetwarzania kart (PCI DSS delegowany); idempotentna obsługa webhooków i zwrotów przy anulowaniu."
    },
    {
      "id": "FR9",
      "description": "RBAC z zasadą najmniejszych uprawnień i row-level security; każde żądanie API niezależnie uwierzytelniane i autoryzowane; dostęp do danych innych użytkowników technicznie niemożliwy bez roli Administratora."
    },
    {
      "id": "FR10",
      "description": "Szyfrowanie danych osobowych AES-256 w spoczynku i TLS 1.3 w tranzycie; zgodność z RODO: eksport danych w 72h i usunięcie w 30 dni na żądanie; szyfrowanie E2E aplikacyjne odroczone do post-MVP (udokumentowany dług techniczny)."
    },
    {
      "id": "FR11",
      "description": "Niemodyfikowalny log audytowy wszystkich operacji (timestamp UTC, ID użytkownika, typ, IP, wynik); retencja 12 miesięcy; hot storage przez 90 dni, następnie tanie cold storage w celu redukcji kosztów."
    },
    {
      "id": "FR12",
      "description": "Powiadomienia email i SMS przez zewnętrznego dostawcę (SendGrid/Twilio) dla: potwierdzenia rezerwacji, przypomnienia 24h przed wizytą, anulowania i modyfikacji terminu przez Specjalistę."
    },
    {
      "id": "FR13",
      "description": "Walidacja danych wejściowych na poziomie API z formalnymi kodami błędów domenowych: BOOKING_CONFLICT, CANCELLATION_WINDOW_EXCEEDED, NO_SLOTS_AVAILABLE, PAYMENT_FAILED, EMAIL_NOT_VERIFIED; komunikaty przyjazne użytkownikowi."
    },
    {
      "id": "FR14",
      "description": "Panel Administratora z raportami KPI (rezerwacje, przychody, anulowania, aktywni użytkownicy) aktualizowanymi co max 1h, eksportem CSV oraz feature flags do konfiguracji wariantów A/B przepływów rezerwacji i modeli cenowych bez wdrożenia kodu."
    },
    {
      "id": "FR15",
      "description": "Automatyczne blokowanie konta po 5 nieudanych logowaniach w 15 min; alerty dla Administratora przy >10 anulowaniach/h lub >5 nieudanych logowaniach/15 min; interfejs mobile-first, WCAG 2.1 poziom A; testy regresji ścieżek krytycznych przed każdym wydaniem."
    }
  ]
}

{
  "acceptance_criteria": [
    {
      "id": "AC1",
      "given": "Nowy użytkownik otwiera formularz rejestracji",
      "when": "Podaje imię, email i hasło min. 10 znaków w 2 krokach i zatwierdza",
      "then": "Konto zostaje utworzone natychmiast; użytkownik może przeglądać terminy i dokonać rezerwacji bez weryfikacji email; wyświetlany jest nieinwazyjny baner zachęcający do weryfikacji przez 7 dni"
    },
    {
      "id": "AC2",
      "given": "Użytkownik posiada konto w systemie",
      "when": "Loguje się przez SSO (Google/Apple) lub email+hasło",
      "then": "Logowanie SSO kończy się w 1 kliknięciu; sesja jest zapamiętana przez 7 dni; przy wykryciu anomalii (zmiana IP/user-agent) wysyłane jest powiadomienie email z opcją potwierdzenia sesji bez automatycznego wylogowania"
    },
    {
      "id": "AC3",
      "given": "Zalogowany użytkownik otwiera widok kalendarza",
      "when": "Stosuje filtry po specjalizacji i dacie",
      "then": "Widok ładuje się poniżej 1 sekundy (p95); wyświetlane są wyłącznie wolne sloty bez danych innych użytkowników"
    },
    {
      "id": "AC4",
      "given": "Zalogowany użytkownik wybiera wolny slot",
      "when": "Przechodzi przez maksymalnie 3 kroki wypełniając maksymalnie 4 pola i zatwierdza rezerwację",
      "then": "Rezerwacja zostaje potwierdzona natychmiast; użytkownik i specjalista otrzymują powiadomienie email i SMS; slot jest zablokowany dla innych użytkowników"
    },
    {
      "id": "AC5",
      "given": "Użytkownik posiada aktywną rezerwację",
      "when": "Klika przycisk anulowania i potwierdza jednorazowo",
      "then": "Jeśli do wizyty pozostało ponad 86400 sekund – anulowanie bezpłatne; jeśli mniej – wymagany wybór powodu z listy dropdown i stosowana polityka zwrotów; każde anulowanie logowane z timestampem UTC"
    },
    {
      "id": "AC6",
      "given": "Zalogowany użytkownik otwiera historię rezerwacji",
      "when": "Przegląda listę wizyt",
      "then": "Każda rezerwacja zawiera status (potwierdzona, anulowana, zakończona), datę, dane specjalisty oraz opcję anulowania dla aktywnych rezerwacji"
    },
    {
      "id": "AC7",
      "given": "Użytkownik posiada potwierdzoną rezerwację",
      "when": "Zbliża się 24h przed terminem wizyty",
      "then": "System automatycznie wysyła powiadomienie email lub SMS z datą, godziną, danymi specjalisty i linkiem do anulowania"
    },
    {
      "id": "AC8",
      "given": "Zalogowany użytkownik żąda eksportu lub usunięcia danych",
      "when": "Składa wniosek przez panel konta",
      "then": "Eksport w formacie JSON lub CSV jest dostępny w ciągu 72h; usunięcie danych następuje w ciągu 30 dni z potwierdzeniem email; dane finansowe są zachowane zgodnie z wymogami prawnymi"
    },
    {
      "id": "AC9",
      "given": "Zalogowany specjalista otwiera panel zarządzania grafikiem",
      "when": "Dodaje, modyfikuje lub usuwa slot dostępności",
      "then": "Zmiany są natychmiast widoczne dla użytkowników; modyfikacja slotu z istniejącą rezerwacją wymaga potwierdzenia specjalisty, jest logowana i wysyła powiadomienie do użytkownika z propozycją alternatywy lub pełnego zwrotu"
    },
    {
      "id": "AC10",
      "given": "Specjalista próbuje zalogować się do systemu",
      "when": "Poda poprawne dane uwierzytelniające",
      "then": "System wymaga obowiązkowego MFA (push notification lub TOTP); logowanie bez MFA jest technicznie niemożliwe; sesja jest ważna przez 8 godzin; hasło musi mieć minimum 12 znaków"
    },
    {
      "id": "AC11",
      "given": "Administrator otwiera panel zarządzania",
      "when": "Aktywuje, blokuje lub zmienia uprawnienia konta albo zmienia reguły systemowe (limity anulowania, modele cenowe)",
      "then": "Zmiana zostaje zastosowana natychmiast; jest zapisana w logu audytowym z ID administratora i timestampem UTC; nie wpływa retroaktywnie na istniejące rezerwacje"
    },
    {
      "id": "AC12",
      "given": "Administrator otwiera sekcję raportów KPI",
      "when": "Przegląda dane lub inicjuje eksport dla wybranego zakresu dat",
      "then": "Dane są aktualne z opóźnieniem maksymalnie 1h; eksport CSV jest dostępny dla dowolnego zakresu dat; dostępne są modele cenowe prowizyjny i subskrypcyjny konfigurowalne przez panel bez wdrożenia kodu"
    },
    {
      "id": "AC13",
      "given": "Administrator otwiera panel feature flags",
      "when": "Włącza lub wyłącza wariant przepływu rezerwacji (np. liczba kroków, treść CTA)",
      "then": "Zmiana wariantu wchodzi w życie natychmiast bez wdrożenia kodu; zdarzenie jest logowane z ID administratora i timestampem; system obsługuje co najmniej 2 aktywne warianty jednocześnie"
    },
    {
      "id": "AC14",
      "given": "System monitoruje aktywność lub administrator otwiera log audytowy",
      "when": "Wykryje ponad 10 anulowań z jednego konta w ciągu godziny lub ponad 5 nieudanych logowań w 15 minut, albo administrator filtruje logi",
      "then": "Administrator otrzymuje automatyczny alert; logi są niemodyfikowalne, dostępne przez minimum 12 miesięcy z filtrowaniem po użytkowniku, typie operacji i zakresie dat; żadna rola nie może ich zmienić ani usunąć"
    },
    {
      "id": "AC15",
      "given": "Administrator weryfikuje tożsamość nowego specjalisty",
      "when": "Zatwierdza aktywację konta specjalisty w panelu",
      "then": "Konto specjalisty zostaje aktywowane natychmiast; zdarzenie jest logowane z ID administratora i timestampem; specjalista może zalogować się dopiero po aktywacji"
    }
  ]
}

